/**
 * Quiz eval (PLAN §9.2): 10 checkpoints × 5 questions generated by makeCheckpoint, each answered
 * blind by verifyQuestions → key agreement (target ≥ 95%), banned options, stem length, option
 * hygiene and answer-position balance. All questions are listed for a human spot check.
 */
import { CheckpointInput, type QuestionDraft, type VerifyResult } from '@engine/brain-contract'
import { checkQuestions } from '../prompts/p05-quiz'
import {
  atLeast,
  atMost,
  type CaseRow,
  type EvalContext,
  loadFixture,
  pool,
  ratio,
  type SuiteResult,
  take,
} from './common'

interface Fixture {
  cases: { id: string; input: CheckpointInput }[]
}

const LETTERS = ['A', 'B', 'C', 'D']

export async function runQuizzes(ctx: EvalContext): Promise<SuiteResult> {
  const fx = loadFixture<Fixture>(ctx.root, 'quizzes.json')
  const cases = take(fx.cases, ctx.limit)
  const outs = await pool(cases, ctx.concurrency, async (c, i) => {
    ctx.log(`quiz ${i + 1}/${cases.length}: ${c.id} (generate)`)
    const questions = await ctx.brain.makeCheckpoint(CheckpointInput.parse(c.input), {
      timeoutMs: ctx.timeoutMs,
    })
    ctx.log(`quiz ${i + 1}/${cases.length}: ${c.id} (verify ${questions.length})`)
    const answers = await ctx.brain.verifyQuestions(questions, { timeoutMs: ctx.timeoutMs })
    return { questions, answers }
  })
  let total = 0
  let agree = 0
  let unanswered = 0
  let errors = 0
  let ruleIssues = 0
  let lowConfidence = 0
  const positions = [0, 0, 0, 0]
  const rows: CaseRow[] = []
  cases.forEach((c, i) => {
    const out = outs[i]
    if (!out || out instanceof Error) {
      errors++
      rows.push({ id: c.id, ok: false, summary: `error: ${out?.message ?? 'none'}`.slice(0, 200) })
      return
    }
    const { questions, answers } = out as { questions: QuestionDraft[]; answers: VerifyResult[] }
    const issues = checkQuestions(questions, c.input.n)
    ruleIssues += issues.length
    let caseAgree = 0
    const lines: string[] = []
    questions.forEach((q, k) => {
      total++
      positions[q.correctIndex] = (positions[q.correctIndex] ?? 0) + 1
      const a = answers.find((x) => x.index === k)
      if (!a) unanswered++
      const ok = a?.chosen === q.correctIndex
      if (ok) {
        agree++
        caseAgree++
      }
      if (a && a.confidence < 0.6) lowConfidence++
      lines.push(
        `  ${k + 1}. ${ok ? '✓' : '✗'} [${q.concept}, d${q.difficulty}] ${q.stem}\n` +
          q.options
            .map(
              (o, j) =>
                `     ${LETTERS[j]}) ${o}${j === q.correctIndex ? '  ← key' : ''}${a?.chosen === j && !ok ? '  ← verifier' : ''}`,
            )
            .join('\n') +
          `\n     verifier: ${a ? `${LETTERS[a.chosen]} (${a.confidence})` : 'no answer'}`,
      )
    })
    rows.push({
      id: c.id,
      ok: caseAgree === questions.length && issues.length === 0,
      summary: `${caseAgree}/${questions.length} keys confirmed${issues.length ? ` · ${issues.join('; ')}` : ''}`,
      detail: lines.join('\n'),
    })
  })
  const agreement = ratio(agree, total)
  return {
    suite: 'quizzes',
    metrics: {
      checkpoints: cases.length,
      errors,
      questions: total,
      keyAgreement: agreement,
      unanswered,
      verifierLowConfidence: lowConfidence,
      ruleIssues,
      keyPositions: positions.map((n, i) => `${LETTERS[i]}:${n}`).join(' '),
    },
    thresholds: [
      atLeast('verifier agrees with the key', agreement, 0.95),
      atMost('rule issues (all/none of the above, duplicates, long stems)', ruleIssues, 0),
      atMost('checkpoints that errored', errors, 0),
    ],
    cases: rows,
    notes: [
      'Distractor quality ("real misconceptions") is a human spot check: read the questions below.',
    ],
  }
}
